package android.os; import java.util.HashMap; public class Bundle extends HashMap<String,Object> { public int getInt(String k,int d){Object v=get(k);return v instanceof Number?((Number)v).intValue():d;} public String getString(String k,String d){Object v=get(k);return v==null?d:String.valueOf(v);} public boolean getBoolean(String k,boolean d){Object v=get(k);return v instanceof Boolean?(Boolean)v:d;} public void putInt(String k,int v){put(k,Integer.valueOf(v));} public void putString(String k,String v){put(k,v);} public void putBoolean(String k,boolean v){put(k,Boolean.valueOf(v));} }